  9→/** Extract a usable email from SendGrid-style fields */
 10→function extractEmail(raw: string): string {
 11→  // Handle "Name <email@domain>" format
 12→  const match = raw.match(/<([^>]+)>/);
 13→  return (match ? match[1] : raw).trim().toLowerCase();
 14→}
 15→
 16→/** Parse recipient from envelope or to field */
 17→function parseRecipient(envelope: string | null, to: string | null): string | null {
 18→  if (envelope) {
 19→    try {
 20→      const env = JSON.parse(envelope);
 21→      if (env.to && Array.isArray(env.to) && env.to.length > 0) return extractEmail(env.to[0]);
 22→    } catch { /* ignore */ }
 23→  }
 24→  if (to) return extractEmail(to.split(",")[0]);
 25→  return null;
 26→}
 27→
 28→/** Parse sender from envelope or from field */
 29→function parseSender(envelope: string | null, from: string | null): string | null {
 30→  if (envelope) {
 31→    try {
 32→      const env = JSON.parse(envelope);
 33→      if (env.from) return extractEmail(env.from);
 34→    } catch { /* ignore */ }
 35→  }
 36→  if (from) return extractEmail(from);
 37→  return null;
 38→}
