 40→serve(async (req) => {
 41→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 42→
 43→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 44→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 45→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 46→
 47→  // Helper to log and respond
 48→  const logAndRespond = async (
 49→    status: number,
 50→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
 51→    responseBody: Record<string, unknown>
 52→  ) => {
 53→    try {
 54→      await supabase.from("email_ingest_logs").insert({
 55→        sender: logData.sender || null,
 56→        recipient: logData.recipient || null,
 57→        user_id: logData.user_id || null,
 58→        job_id: logData.job_id || null,
 59→        status: logData.status,
 60→        error_message: logData.error_message || null,
 61→        attachments_count: logData.attachments_count || 0,
 62→        resumes_created: logData.resumes_created || 0,
 63→      });
 64→    } catch (e) {
 65→      console.error("Failed to log email ingest:", e);
 66→    }
 67→    return new Response(JSON.stringify(responseBody), {
 68→      status,
 69→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 70→    });
 71→  };
 72→
 73→  try {
 74→    // Check global email ingestion toggle
 75→    const { data: config } = await supabase
 76→      .from("platform_config")
 77→      .select("email_ingestion_enabled")
 78→      .limit(1)
 79→      .single();
 80→
 81→    if (config && !config.email_ingestion_enabled) {
 82→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
 83→    }
 84→
 85→    // Parse incoming payload — support both multipart/form-data (SendGrid/Mailgun) and JSON
 86→    let sender: string | null = null;
 87→    let recipient: string | null = null;
 88→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
 89→
 90→    const contentType = req.headers.get("content-type") || "";
 91→
 92→    if (contentType.includes("multipart/form-data")) {
 93→      // SendGrid Inbound Parse / Mailgun Routes format
 94→      const formData = await req.formData();
 95→
 96→      const envelope = formData.get("envelope") as string | null;
 97→      const fromField = formData.get("from") as string | null;
 98→      const toField = formData.get("to") as string | null;
 99→
100→      sender = parseSender(envelope, fromField);
101→      recipient = parseRecipient(envelope, toField);
102→
103→      // Extract attachments — SendGrid sends them as file parts
104→      // Attachment count is in "attachments" field as a number
105→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
106→
107→      for (let i = 1; i <= Math.max(attachmentCount, 10); i++) {
108→        const file = formData.get(`attachment${i}`) as File | null;
109→        if (!file) continue;
110→        const buffer = await file.arrayBuffer();
111→        attachmentFiles.push({
112→          filename: file.name || `attachment_${i}`,
113→          content: new Uint8Array(buffer),
114→        });
115→      }
116→
117→      // Also check for "attachment-info" pattern (some providers)
118→      if (attachmentFiles.length === 0) {
119→        for (const [key, value] of formData.entries()) {
120→          if (key.startsWith("attachment") && value instanceof File) {
121→            const buffer = await value.arrayBuffer();
122→            attachmentFiles.push({
123→              filename: value.name || key,
124→              content: new Uint8Array(buffer),
125→            });
126→          }
127→        }
128→      }
129→    } else {
130→      // Legacy JSON format (backward compatible)
131→      const body = await req.json();
132→      sender = body.sender || null;
133→      recipient = body.recipient || null;
134→
135→      if (body.attachments && Array.isArray(body.attachments)) {
136→        for (const att of body.attachments) {
137→          if (!att.filename || !att.content) continue;
138→          const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
139→          attachmentFiles.push({ filename: att.filename, content: fileContent });
140→        }
141→      }
142→    }
143→
144→    if (!recipient) {
145→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
146→    }
147→
148→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
149→    let jobId: string | null = null;
150→    let userId: string | null = null;
151→
152→    const { data: jobMatch } = await supabase
153→      .from("jobs")
154→      .select("id, user_id")
155→      .eq("inbox_email", recipient)
156→      .single();
157→
158→    if (jobMatch) {
159→      jobId = jobMatch.id;
160→      userId = jobMatch.user_id;
161→    }
162→
163→    // Step 2: Fall back to user-level inbox routing
164→    if (!userId) {
165→      // Strip +tag for matching: abc+xyz@domain → abc@domain
166→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
167→
168→      const { data: profile } = await supabase
169→        .from("profiles")
170→        .select("user_id, credits, email_enabled, inbox_email")
171→        .or(`inbox_email.eq.${recipient},inbox_email.eq.${baseRecipient}`)
172→        .limit(1)
173→        .single();
174→
175→      if (!profile) {
176→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
177→      }
178→
179→      userId = profile.user_id;
180→
181→      // Check per-user email toggle
182→      if (!profile.email_enabled) {
183→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
184→      }
185→    } else {
186→      // Verify the job owner has email enabled
187→      const { data: profile } = await supabase
188→        .from("profiles")
189→        .select("email_enabled")
190→        .eq("user_id", userId)
191→        .single();
192→
193→      if (profile && !profile.email_enabled) {
194→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
195→      }
196→    }
197→
198→    if (attachmentFiles.length === 0) {
199→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No attachments" }, { error: "No attachments" });
200→    }
201→
202→    // Find or create job if not already matched by per-job routing
203→    if (!jobId) {
204→      const { data: activeJob } = await supabase
205→        .from("jobs")
206→        .select("id")
207→        .eq("user_id", userId)
208→        .eq("status", "pending")
209→        .order("created_at", { ascending: false })
210→        .limit(1)
211→        .single();
212→
213→      if (activeJob) {
214→        jobId = activeJob.id;
215→      } else {
216→        const { data: newJob } = await supabase
217→          .from("jobs")
218→          .insert({
219→            user_id: userId,
220→            job_description: "Auto-created from email ingestion",
221→            status: "pending",
222→          })
223→          .select("id")
224→          .single();
225→        if (!newJob) throw new Error("Failed to create job");
226→        jobId = newJob.id;
227→      }
228→    }
229→
230→    // Process attachments
231→    const resumeIds: string[] = [];
232→    for (const att of attachmentFiles) {
233→      const filePath = `${userId}/${jobId}/${Date.now()}_${att.filename}`;
234→      await supabase.storage.from("resumes").upload(filePath, att.content);
235→
236→      const { data: resume } = await supabase
237→        .from("resumes")
238→        .insert({
239→          job_id: jobId,
240→          filename: att.filename,
241→          file_path: filePath,
242→          source: "email",
243→        })
244→        .select("id")
245→        .single();
246→
247→      if (resume) resumeIds.push(resume.id);
248→    }
249→
250→    // Send confirmation email to the user (fire-and-forget)
251→    try {
252→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
253→      const userEmail = authUser?.user?.email;
254→
255→      if (userEmail) {
256→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
257→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
258→
259→        await supabase.functions.invoke("send-email", {
260→          body: {
261→            to: userEmail,
262→            template_key: "resume_received",
263→            variables: {
264→              user_name: userEmail.split("@")[0],
265→              job_title: jobTitle,
266→              attachment_count: String(attachmentFiles.length),
267→              filename: attachmentFiles.map((a) => a.filename).join(", "),
268→              job_id: jobId || "",
269→              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
270→            },
271→          },
272→        });
273→      }
274→    } catch (emailErr) {
275→      console.error("Failed to send resume received notification:", emailErr);
276→    }
277→
278→    return await logAndRespond(
279→      200,
280→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: attachmentFiles.length, resumes_created: resumeIds.length },
281→      { success: true, resume_ids: resumeIds, job_id: jobId }
282→    );
283→  } catch (err: unknown) {
284→    console.error("email-ingest error:", err);
285→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
286→      status: 500,
287→      headers: { ...corsHeaders, "Content-Type": "application/json" },
288→    });
289→  }
290→});
